import pLimit from 'p-limit';
const limit = pLimit(10); // Maximum 10 concurrent requests
const tasks = items.map(item => limit(() => processItem(item)));
const results = await Promise.all(tasks);

try {
  const res = await fetch('https://api.internal/data', {
    signal: AbortSignal.timeout(3000) // 3-second timeout
  });
} catch (err) {
  if (err.name === 'TimeoutError') console.error('Request timed out');
}

